// 1. Export Dry Loops
for (const l of state.loops) {
    if (l.audioBuffer) {
        try {
            const loopName = (l.name || `Loop_${l.id + 1}`).replace(/[^a-z0-9]/gi, '_');				
            // Export full loop, startDelay is a realtime parameter
            const wavData = AudioEngine.bufferToWAV(l.audioBuffer);
            this.downloadWAV(wavData, `${safeName}_${loopName}_${ts}.wav`);
            exported++; 
        }
        catch (e) { errors.push(`Dry loop ${l.id + 1}: ${e.message}`); }
    }
}

// Snapshot all dry takes before awaiting the first encode.
const dryExports = state.loops.filter(l => l.audioBuffer).map(l => {
    const id = l.id;
    try {
        const name = (l.name || `Loop_${id + 1}`).replace(/[^a-z0-9]/gi, '_');
        const work = window.RustLooper.encodeWAVBuffer(l.audioBuffer)
            .then(wav => ({wav}), error => ({error}));
        return {id, name, work};
    } catch(error) { return {id, work: Promise.resolve({error})}; }
});
for (const item of dryExports) {
    try {
        const result = await item.work;
        if (result.error) throw result.error;
        this.downloadWAV(result.wav, `${safeName}_${item.name}_${ts}.wav`);
        exported++;
    } catch(e) { errors.push(`Dry loop ${item.id + 1}: ${e.message}`); }
}
